d|国民党軍の攻撃を受けた共産党は、瑞金から陝西省の延安まで長征（1934〜36）を行った。共産党が八・一宣言（1935）で内戦停止と抗日民族統一戦線を呼びかけ、張学良が蔣介石を監禁して内戦停止を求めた西安事件（1936）を経て、日中戦争開始後に第2次国共合作が成立した（1937）。
